const cds = require('../../../cds')
const { path, sh: $ } = cds.utils
const { renderAndCopy } = require('../../template')

module.exports = class VueTemplate extends require('../../plugin') {

  options() {
    return {
      'into': {
        type: 'string',
        short: 'i',
        help: `Name of the app folder in 'app/'. Example: 'catalog' → 'app/catalog'. Omit for a single-UI scenario where the Vite app sits directly in 'app/'.`
      }
    }
  }

  static help() {
    return 'user interface for Vue.js'
  }

  async run() {
    const into = cds.cli.options.into
    const isRoot = !into || into === '.' || into === ''
    const app = isRoot ? path.basename(cds.root) : into
    const target = isRoot ? cds.env.folders.app : path.join(cds.env.folders.app, into)
    await renderAndCopy(path.join(__dirname, 'files'), target, {
      app,
      isJava: cds.env['project-nature'] === 'java',
      isRoot,
      base: isRoot ? '/' : `/${into}/`,
      archiveName: isRoot ? app : into,
      literal: () => text => text,
    })
    let prefix = target
    if (cds.cli.command === 'init') prefix = path.join(cds.cli.argv[0], target)
    await $`npm i --prefix ${prefix}`
  }
}
